#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be UPROPERTY: ScoreTracker is a UObject created with NewObject. Without
	// a UPROPERTY() it is not referenced by the actor and gets garbage collected
	// during play, leaving this pointer dangling (shipping crash in AddPoints).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker was created with NewObject but declared as a raw pointer without UPROPERTY(), so nothing referenced it for the garbage collector. In the packaged build GC purged it during play (log: 'Collecting garbage: 412 objects purged' shortly before 'LogGarbage'), leaving a dangling pointer; the first goal then called AArenaGameMode::OnGoalScored -> UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) on the freed object, causing EXCEPTION_ACCESS_VIOLATION. Fix: made ScoreTracker a UPROPERTY() TObjectPtr in ArenaGameMode.h.",
  "no_colors_cause": "The arena palette data asset /Game/Data/Palettes/DA_Primary was never cooked into the packaged build: DefaultGame.ini has bCookAll=False and DirectoriesToAlwaysCook only listed /Game/Data/Effects, not /Game/Data/Palettes. LoadObject therefore failed in shipping (log: \"LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary\" and 'Palette is null, using fallback gray'), so the HUD rendered everything in gray. In the editor the asset loads from loose files, which is why colors worked there. Fix: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini.",
  "assumptions": [
    "Missing sources (ArenaHud, ArenaPalette, ArenaScoreTracker, ArenaStats) exist in the full project but were not included in this workspace; only the files present were edited.",
    "The arena map /Game/Maps/Arena already cooks its own assets; only the runtime-loaded palette data asset needed an explicit cook directory.",
    "The ~1-minute delay before the crash matches the first GC pass happening after gameplay started, not the goal event itself."
  ]
}
